<?php
namespace App\Http\Controllers; use App\Models\{User,Waste,Deposit,Withdrawal,AccountLedger,Complaint,AppNotification};
class DashboardController extends Controller {public function index(){ $u=auth()->user(); $notifications=AppNotification::where('user_id',$u->id)->latest()->take(5)->get(); if($u->role==='nasabah'){return view('dashboard.index',['role'=>$u->role,'balance'=>$u->balance(),'totalDeposits'=>$u->deposits()->where('status','completed')->sum('total_amount'),'activeDeposits'=>$u->deposits()->whereIn('status',['pending','weighed'])->count(),'withdrawals'=>$u->withdrawals()->latest()->take(5)->get(),'recentDeposits'=>$u->deposits()->latest()->take(5)->get(),'notifications'=>$notifications]);} return view('dashboard.index',['role'=>$u->role,'customers'=>User::where('role','nasabah')->count(),'wastes'=>Waste::count(),'todayDeposits'=>Deposit::whereDate('deposit_date',today())->count(),'totalCollected'=>Deposit::where('status','completed')->sum('total_amount'),'pendingWithdrawals'=>Withdrawal::where('status','pending')->count(),'openComplaints'=>Complaint::whereIn('status',['open','processed'])->count(),'recentDeposits'=>Deposit::with('customer')->latest()->take(6)->get(),'notifications'=>$notifications]);}}
